import * as THREE from './vendor/three/three.module.js';
import { createMoon, createSun } from './models/celestial.js';
import { createLunarTextures } from './models/lunar-surface.js';
import { createStar, createRecord } from './models/sculpted.js';

// The shared renderer draws real meshes in one 3D scene. Its transparent frame
// is composited between the hand skeleton and particles by UniverseScene.
// Texture pixels, surface geometry and animation are all generated by code.
function studioEnvironment(renderer) {
  const canvas = document.createElement('canvas');
  canvas.width = 512; canvas.height = 256;
  const ctx = canvas.getContext('2d');
  const background = ctx.createLinearGradient(0, 0, 0, 256);
  background.addColorStop(0, '#b3ada0');
  background.addColorStop(.38, '#67695f');
  background.addColorStop(.55, '#252c2c');
  background.addColorStop(1, '#3c3628');
  ctx.fillStyle = background; ctx.fillRect(0, 0, 512, 256);
  for (const [x, y, radius, color] of [[105, 65, 70, '#fff9e5'], [385, 105, 42, '#dfecf3'], [245, 50, 25, '#e9dcba']]) {
    const glow = ctx.createRadialGradient(x, y, 0, x, y, radius);
    glow.addColorStop(0, color); glow.addColorStop(.45, color); glow.addColorStop(1, 'transparent');
    ctx.fillStyle = glow; ctx.fillRect(x-radius, y-radius, radius*2, radius*2);
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.mapping = THREE.EquirectangularReflectionMapping;
  const generator = new THREE.PMREMGenerator(renderer);
  const target = generator.fromEquirectangular(texture);
  generator.dispose(); texture.dispose();
  return target;
}

export class Objects3D {
  constructor() {
    this.renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, powerPreference: 'high-performance' });
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.14;
    this.scene = new THREE.Scene();
    this.camera = new THREE.OrthographicCamera(-640, 640, 360, -360, .1, 4000);
    this.camera.position.z = 1600;
    this.environment = studioEnvironment(this.renderer);
    this.scene.environment = this.environment.texture;
    this.scene.environmentIntensity = .85;
    this.scene.add(new THREE.HemisphereLight('#f9edcf', '#3b423d', 1.35));
    for (const [color, intensity, x, y, z] of [['#fff4d8', 3.2, -600, 750, 1200], ['#c5e1ef', 1.15, 750, 200, 650], ['#d0c3a1', .8, -400, -550, 200]]) {
      const light = new THREE.DirectionalLight(color, intensity);
      light.position.set(x, y, z); this.scene.add(light);
    }
    this.clock = 0; this.sunClock = 0; this.recordClock = 0;
    this.recordPlaying = false; this.ready = false;
    this.pools = { star: [], sun: [], moon: [], record: [] };
    this.commands = []; this.counts = {};
    this.baseOpacities = new WeakMap();
    this.assetsReady = this.initialize();
  }

  async initialize() {
    this.lunarTextures = createLunarTextures({ width: 1536 });
    this.moonFactory = options => createMoon({ ...this.lunarTextures, ...options });
    this.factories = {
      star: createStar, sun: createSun, moon: this.moonFactory,
      record: () => createRecord({ createMoon: this.moonFactory }),
    };
    for (const [kind, count] of [['star', 1], ['sun', 1], ['moon', 6], ['record', 1]]) {
      for (let i = 0; i < count; i++) this.instance(kind, i);
    }
    await this.renderer.compileAsync(this.scene, this.camera);
    this.ready = true;
    this.beginFrame();
    return this;
  }

  instance(kind, index) {
    const pool = this.pools[kind];
    if (!pool[index]) {
      const model = this.factories[kind]();
      model.object.userData.kind = kind;
      model.object.traverse(child => {
        for (const material of child.material ? (Array.isArray(child.material) ? child.material : [child.material]) : []) {
          const base = material.uniforms?.uOpacity?.value ?? material.opacity;
          this.baseOpacities.set(material, base);
          // Fades are controlled uniformly for the shell, solid and metal parts.
          material.transparent = true;
        }
      });
      pool.push(model); this.scene.add(model.object);
    }
    return pool[index];
  }

  resize(width, height) {
    this.width = Math.max(width, 1); this.height = Math.max(height, 1);
    this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 2));
    this.renderer.setSize(this.width, this.height, false);
    this.camera.left = -this.width/2; this.camera.right = this.width/2;
    this.camera.top = this.height/2; this.camera.bottom = -this.height/2;
    this.camera.updateProjectionMatrix();
  }

  update(dt, { mode, dissolved, recordPlaying, sunVisible = mode === 'sun' }) {
    this.clock += dt;
    if (sunVisible && !dissolved) this.sunClock += dt;
    this.recordPlaying = mode === 'pan' && !dissolved && recordPlaying;
    if (this.recordPlaying) this.recordClock += dt;
  }

  resetClocks() {
    this.clock = this.sunClock = this.recordClock = 0;
    this.recordPlaying = false;
    for (const model of this.pools.record) model.reset?.();
  }

  beginFrame() {
    this.commands = []; this.counts = {};
    for (const pool of Object.values(this.pools)) for (const model of pool) model.object.visible = false;
  }

  draw(kind, x, y, radius, opacity = 1, options = {}) {
    if (!this.ready || opacity <= .001 || radius <= 0) return;
    const index = this.counts[kind] || 0;
    this.counts[kind] = index + 1;
    const model = this.instance(kind, index);
    const time = kind === 'record' ? this.recordClock : kind === 'sun' ? this.sunClock : this.clock;
    model.update(time, { ...options, playing: this.recordPlaying });
    model.object.position.set(x-this.width/2, this.height/2-y, 0);
    model.object.scale.setScalar(radius);
    model.object.visible = true;
    model.object.traverse(child => {
      for (const material of child.material ? (Array.isArray(child.material) ? child.material : [child.material]) : []) {
        const alpha = this.baseOpacities.get(material) * Math.min(1, Math.max(0, opacity));
        if (material.uniforms?.uOpacity) material.uniforms.uOpacity.value = alpha;
        else material.opacity = alpha;
      }
    });
    this.commands.push({ kind, phase: options.phase ?? null, x, y, radius, opacity, model });
  }

  render(context) {
    this.renderer.render(this.scene, this.camera);
    if (context) context.drawImage(this.renderer.domElement, 0, 0, this.width, this.height);
  }

  get state() {
    return {
      ready: this.ready, backend: 'WebGL2', clock: this.clock,
      sunClock: this.sunClock, recordClock: this.recordClock, recordPlaying: this.recordPlaying,
      drawCalls: this.renderer.info.render.calls, triangles: this.renderer.info.render.triangles,
      activeObjects: this.commands.map(({ model, ...command }) => command),
      imageAssets: [], videoTextures: 0,
    };
  }

  dispose() {
    for (const pool of Object.values(this.pools)) for (const model of pool) model.dispose();
    this.lunarTextures?.dispose(); this.environment.dispose(); this.renderer.dispose();
  }
}
